package rustanything;

import java.lang.reflect.Type;
import java.util.*;

/** Generated by rust-anything: calls the Rust port of `com/guocheng/mediapocket/rules/` through JNI. */
public final class RulesRsNative {
    private RulesRsNative() {}

    static {
        String path = System.getProperty("rust-anything.lib.rules_rs");
        if (path != null) {
            System.load(path);
        } else {
            System.loadLibrary("rules_rs");
        }
    }

    private static native String call(String name, String args);

    // Typed methods: primitives and strings cross JNI directly, without JSON.
    public static native String n_className(String api, String[] slot);
    public static native String n_md5(String declaration, String[] slot);
    public static native String n_checkLabel(String code, int bytes, String[] slot);

    public static String call_className(String api) {
        try {
            String[] slot = RustAnythingError.slot();
            String out = n_className(api, slot);
            RustAnythingError.check(slot);
            return out;
        } catch (RustAnythingError e) {
            throw e.real();
        }
    }

    public static String call_md5(String declaration) {
        try {
            String[] slot = RustAnythingError.slot();
            String out = n_md5(declaration, slot);
            RustAnythingError.check(slot);
            return out;
        } catch (RustAnythingError e) {
            throw e.real();
        }
    }

    public static String call_checkLabel(String code, int bytes) {
        try {
            String[] slot = RustAnythingError.slot();
            String out = n_checkLabel(code, bytes, slot);
            RustAnythingError.check(slot);
            return out;
        } catch (RustAnythingError e) {
            throw e.real();
        }
    }


    /** Calls the port of {@code name}; its answer is converted to {@code type}. */
    public static Object invoke(String name, Type type, Object... args) {
        String answer = call(name, RustAnythingJson.write(java.util.Arrays.asList(args)));
        @SuppressWarnings("unchecked")
        Map<String, Object> parsed = (Map<String, Object>) RustAnythingJson.parse(answer);
        if (parsed.containsKey("ok")) {
            return type == void.class ? null : RustAnythingJson.convert(parsed.get("ok"), type);
        }
        String message = parsed.containsKey("error")
            ? String.valueOf(parsed.get("error"))
            : "Rust panic: " + parsed.get("panic");
        throw RustAnythingError.from(message);
    }
}
